<script setup>
import { computed, ref } from 'vue'
import { Archive, Award, Bell, BookOpen, CalendarClock, Check, ChefHat, ChevronRight, CircleAlert, ClipboardCheck, FilePlus2, FolderLock, LayoutDashboard, Lock, Menu, Plus, RotateCcw, Search, ShieldCheck, Trash2, TrendingUp, UserRound, X } from 'lucide-vue-next'
import { config, days, today } from './data'
import { useKeeper } from './composables/useKeeper'
import { buildRanking, evaluateAchievements } from './services/achievements'
const { state, add, update, remove, reset, clear, metrics } = useKeeper()
const active = ref('overview'); const query = ref(''); const showForm = ref(false); const mobileOpen = ref(false); const draft = ref({})
const showCook = ref(false); const cookDraft = ref({})
const activeNav = computed(() => config.nav.find((x) => x.id === active.value))
const docs = computed(() => state.documents.filter((x) => `${x.name}${x.holder}${x.category}`.toLowerCase().includes(query.value.toLowerCase())))
const alerts = computed(() => state.documents.map((x) => ({ ...x, remaining: days(x.expires) })).filter((x) => x.remaining <= 90).sort((a, b) => a.remaining - b.remaining))
const completedCount = computed(() => state.usages.filter((x) => x.status === '完成').length)
const completion = computed(() => Math.min(100, Math.round((state.documents.filter((x) => x.location && x.copyLocation).length / Math.max(state.documents.length, 1)) * 100)))
// 徽章完全由当前状态计算：新数据一律未解锁，数据清空后自动回退
const badges = computed(() => evaluateAchievements(state))
const unlockedCount = computed(() => badges.value.filter((x) => x.unlocked).length)
const ranking = computed(() => buildRanking(state))
function openCreate() { draft.value = Object.fromEntries(config.form.fields.map(([key, , value]) => [key, value || ''])); showForm.value = true }
function save() { add(config.form.collection, { ...draft.value }); showForm.value = false }
function readFile(event) { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { draft.value.photo = reader.result }; reader.readAsDataURL(file) }
function openCook(recipe) {
  cookDraft.value = { documentId: recipe?.id || state.documents[0]?.id || '', purpose: '', borrower: '林小满', date: today, status: '完成', score: 5, note: '' }
  showCook.value = true
}
function saveCook() {
  if (!cookDraft.value.documentId) return
  add('usages', { ...cookDraft.value, score: Number(cookDraft.value.score) })
  // 同步菜谱的“最近烹饪日期”
  update('documents', cookDraft.value.documentId, { issued: cookDraft.value.date })
  showCook.value = false
}
function deleteUsage(id) { remove('usages', id) }
function togglePurchase(item) { update('policies', item.id, { done: !item.done, payment: item.done ? '未采购' : '已采购' }) }
function resetDemo() { if (window.confirm('恢复演示数据会覆盖当前的菜谱与烹饪记录，确定继续吗？')) reset() }
function clearData() { if (window.confirm('将清空全部菜谱、烹饪记录与菜单，回到新用户状态，确定继续吗？')) clear() }
function markRenewed(doc) { update('documents', doc.id, { expires: `${new Date().getFullYear() + 10}-12-31`, renewed: true }) }
function navTo(id) { active.value = id; mobileOpen.value = false }
</script>
<template>
  <div class="app-shell">
    <aside class="sidebar" :class="{ open: mobileOpen }"><div class="brand"><span class="brand-mark"><FolderLock :size="19" /></span><div><strong>{{ config.brand }}</strong><small>{{ config.subtitle }}</small></div><button class="icon-btn close" @click="mobileOpen = false"><X :size="17" /></button></div><div class="family-chip"><span>林</span><div><b>林家家庭空间</b><small>4 位成员 · 私密存储</small></div><ChevronRight :size="15" /></div><nav><button v-for="item in config.nav" :key="item.id" :class="{ active: active === item.id }" @click="navTo(item.id)"><component :is="item.id === 'overview' ? LayoutDashboard : item.id === 'documents' ? Archive : item.id === 'history' ? CalendarClock : item.id === 'insurance' ? ShieldCheck : Award" :size="17" /><span>{{ item.label }}</span><i v-if="item.id === 'documents' && alerts.length">{{ alerts.length }}</i></button></nav><div class="sidebar-foot"><button><BookOpen :size="17" />使用指南</button><button><UserRound :size="17" />个人中心</button><button class="reset" @click="resetDemo"><RotateCcw :size="15" />恢复演示数据</button><button class="reset danger" @click="clearData"><Trash2 :size="15" />清空我的数据</button></div></aside>
    <main class="main"><header class="topbar"><button class="icon-btn menu" @click="mobileOpen = true"><Menu :size="20" /></button><div><span class="eyebrow">家庭厨房空间</span><h1>{{ activeNav.label }}</h1></div><div class="top-actions"><button class="icon-btn"><Bell :size="18" /><em v-if="alerts.length"></em></button><span class="avatar">林</span><b>Lin</b></div></header>
      <div class="page">
        <section class="intro"><div><span class="eyebrow">{{ active === 'overview' ? '星期三 · 2026年10月7日' : '数据随时保存在当前设备' }}</span><h2>{{ active === 'overview' ? config.heroTitle : activeNav.label }}</h2><p>{{ active === 'overview' ? config.heroCopy : '集中查看、编辑和追踪家庭菜谱。' }}</p></div><button class="primary" @click="active === 'history' || active === 'achievements' ? openCook() : openCreate()"><component :is="active === 'history' || active === 'achievements' ? ChefHat : Plus" :size="16" />{{ active === 'history' || active === 'achievements' ? '记录烹饪' : (config.createLabel || '新建档案') }}</button></section>
        <section v-if="active === 'overview'" class="metric-grid"><article v-for="metric in metrics" :key="metric.label" class="metric"><span class="metric-icon" :class="metric.tone"><Archive v-if="metric.tone === 'green'" :size="17" /><CalendarClock v-else-if="metric.tone === 'peach'" :size="17" /><CircleAlert v-else-if="metric.tone === 'red'" :size="17" /><ShieldCheck v-else :size="17" /></span><div><small>{{ metric.label }}</small><strong>{{ metric.value }}</strong><em>{{ metric.tone === 'red' && metric.value !== '0.0' ? '继续保持水准' : metric.tone === 'peach' && metric.value ? '本月已在开火' : '较上月稳定' }}</em></div></article></section>
        <section v-if="active === 'overview'" class="content-grid"><article class="panel"><div class="panel-head"><div><span class="eyebrow">推荐再做</span><h3>需要你留意的菜谱</h3></div><button class="text-btn" @click="navTo('documents')">查看全部 <ChevronRight :size="14" /></button></div><div class="alert-list"><div v-for="item in alerts.slice(0, 4)" :key="item.id" class="alert-row"><span class="alert-icon" :class="item.remaining < 0 ? 'danger' : 'warn'"><CircleAlert :size="16" /></span><div><b>{{ item.name }}</b><small>{{ item.holder }} · {{ item.location || '家常味道' }}</small></div><span class="date-pill" :class="item.remaining < 0 ? 'danger' : 'warn'">{{ item.remaining < 0 ? `已超过 ${Math.abs(item.remaining)} 天没做` : `${item.remaining} 天后可再做` }}</span><button v-if="item.remaining <= 90" class="tiny-btn" @click="openCook(item)">做一次</button></div><div v-if="!alerts.length" class="empty">暂无到期提醒，去记录一次烹饪吧。</div></div></article><article class="panel score"><div class="panel-head"><div><span class="eyebrow">菜谱完整度</span><h3>家庭菜谱健康度</h3></div><TrendingUp :size="18" class="accent" /></div><div class="score-ring"><strong>{{ completion }}<small>%</small></strong></div><p>每道菜谱都有食材和调料清单，下厨时可以快速备料。</p><div class="progress"><span :style="{ width: `${completion}%` }"></span></div><small class="muted">已完善 {{ state.documents.filter(x => x.location && x.copyLocation).length }} / {{ state.documents.length }} 份</small></article></section>
        <section v-else-if="active === 'documents'" class="panel"><div class="toolbar"><div class="search"><Search :size="16" /><input v-model="query" :placeholder="`搜索${config.entityLabel}`" /></div><select><option>全部类别</option><option v-for="item in config.categories" :key="item">{{ item }}</option></select></div><div class="table-head"><span>{{ config.entityLabel }}</span><span>菜系 / 难度</span><span>{{ config.dateLabel || '最近烹饪' }}</span><span>{{ config.locationLabel || '食材' }}</span><span>操作</span></div><div v-for="item in docs" :key="item.id" class="table-row"><div class="item-title"><span class="file-icon"><Archive :size="16" /></span><div><b>{{ item.name }}</b><small>{{ item.number || '未填写时间' }}</small></div></div><span><b>{{ item.category }}</b><small>{{ item.holder }}</small></span><span><b :class="{ dangerText: days(item.expires) < 0, warnText: days(item.expires) >= 0 && days(item.expires) <= 90 }">{{ item.issued || '—' }}</b><small>{{ days(item.expires) < 0 ? '推荐日期已过' : `${config.remainingPrefix || '建议再做'} ${days(item.expires)} 天` }}</small></span><span><b>{{ item.location || '未填写' }}</b><small>{{ config.copyLabel || '调料' }}：{{ item.copyLocation || '未填写' }}</small></span><button class="tiny-btn" @click="openCook(item)"><ChefHat :size="12" />记录烹饪</button></div><div v-if="!docs.length" class="empty">还没有菜谱，先添加一道，再记录它的第一次烹饪吧。</div></section>
        <section v-else-if="active === 'history'" class="panel"><div class="panel-head"><div><span class="eyebrow">{{ config.historyLabel }}</span><h3>{{ config.historyTitle || `${config.entityLabel}历史` }}</h3></div><div class="head-actions"><span class="count-note">已完成 {{ completedCount }} 条</span><button class="tiny-btn" @click="openCook()"><Plus :size="12" />记录烹饪</button></div></div><div class="history-grid"><div v-for="entry in state.usages" :key="entry.id" class="history-card"><div class="history-date"><span>{{ entry.date }}</span><span class="history-tools"><span :class="entry.status === '完成' ? 'goodText' : 'warnText'">{{ entry.status }}</span><button class="icon-btn xs" title="删除记录" @click="deleteUsage(entry.id)"><Trash2 :size="13" /></button></span></div><b>{{ state.documents.find(x => x.id === entry.documentId)?.name || '已删除的菜谱' }}</b><p>{{ entry.purpose || '家常一餐' }} · 经办人 {{ entry.borrower }}<template v-if="entry.status === '完成'"> · {{ entry.score || 0 }} 星</template></p><small>{{ entry.note || '无备注' }}</small></div></div><div v-if="!state.usages.length" class="empty">还没有任何烹饪记录。做一顿饭并记录下来，才能点亮“初次下厨”徽章。</div></section>
        <section v-else-if="active === 'insurance'" class="panel"><div class="panel-head"><div><span class="eyebrow">{{ config.secondaryLabel }}</span><h3>{{ config.secondaryTitle || config.secondaryLabel }}</h3></div><button class="text-btn" @click="openCreate">{{ config.secondaryAction || '添加记录' }} <Plus :size="14" /></button></div><div class="policy-grid"><div v-for="item in state.policies" :key="item.id" class="policy-card"><div class="policy-logo" :class="{ done: item.done }"><component :is="item.done ? ClipboardCheck : ShieldCheck" :size="20" /></div><div><b>{{ item.type }}</b><small>{{ item.company }} · {{ item.number }}</small></div><span class="policy-date">{{ config.secondaryDatePrefix || '周' }} {{ item.expires }}</span><strong>{{ item.done ? '已就绪' : '待采购' }} <small>{{ item.payment || item.meta || '' }}</small></strong><button class="tiny-btn" :class="{ ghost: item.done }" @click="togglePurchase(item)"><Check v-if="!item.done" :size="12" />{{ item.done ? '撤销采购' : '标记已采购' }}</button><p>{{ item.insured || item.description || '已加入家庭计划' }}</p></div></div><div v-if="!state.policies.length" class="empty">还没有安排菜单，采购完成后可点亮“采购有序”徽章。</div></section>
        <section v-else class="content-grid"><article class="panel"><div class="panel-head"><div><span class="eyebrow">成长记录</span><h3>成就徽章</h3></div><span class="count-note">{{ unlockedCount }}/{{ badges.length }} 已点亮</span></div><p v-if="!state.usages.length" class="badge-hint">还没有烹饪记录。徽章只会根据真实的烹饪行为解锁——去记录第一次下厨吧。</p><div class="badge-grid"><div v-for="item in badges" :key="item.id" class="badge" :class="{ unlocked: item.unlocked }"><span><component :is="item.unlocked ? item.icon : Lock" :size="18" /></span><b>{{ item.name }}</b><small>{{ item.unlocked ? '已解锁' : `待解锁 · ${item.current}/${item.target}` }}</small><em>{{ item.desc }}</em></div></div></article><article class="panel"><div class="panel-head"><div><span class="eyebrow">家庭榜单</span><h3>家庭烹饪达人</h3></div><Award :size="18" class="accent" /></div><div v-for="(row, index) in ranking" :key="row.name" class="rank"><b>{{ String(index + 1).padStart(2, '0') }}</b><span class="rank-avatar" :class="{ alt: index === 1 }">{{ row.name.slice(0, 1) }}</span><div><b>{{ row.name }}</b><small>烹饪 {{ row.count }} 次 · 平均 {{ row.avg }} 星</small></div><strong>{{ row.points }}</strong></div><div v-if="!ranking.length" class="empty">榜单还空着，完成第一条烹饪记录即可上榜。</div></article></section>
      </div>
    </main>
    <div v-if="showForm" class="modal-backdrop" @click.self="showForm = false"><form class="modal" @submit.prevent="save"><div class="modal-head"><div><span class="eyebrow">建立家庭菜谱</span><h3>{{ config.form.title }}</h3></div><button type="button" class="icon-btn" @click="showForm = false"><X :size="17" /></button></div><div class="form-grid"><label v-for="[key, label, placeholder, type] in config.form.fields" :key="key" :class="{ wide: key === 'notes' }">{{ label }}<input v-model="draft[key]" :type="type || 'text'" :placeholder="placeholder" /></label><label class="wide upload-field">照片或成品图（可选）<input type="file" accept="image/*" @change="readFile" /><small>{{ draft.photo ? '已读取图片，可随菜谱保存' : '支持 JPG、PNG，内容仅保存在本机' }}</small></label></div><div class="modal-actions"><button type="button" class="secondary" @click="showForm = false">取消</button><button class="primary" type="submit"><FilePlus2 :size="16" />保存菜谱</button></div></form></div>
    <div v-if="showCook" class="modal-backdrop" @click.self="showCook = false"><form class="modal" @submit.prevent="saveCook"><div class="modal-head"><div><span class="eyebrow">真实烹饪行为</span><h3>记录一次烹饪</h3></div><button type="button" class="icon-btn" @click="showCook = false"><X :size="17" /></button></div><div class="form-grid"><label class="wide">做的是哪道菜<select v-model="cookDraft.documentId" required><option value="" disabled>请选择菜谱（没有菜谱请先添加）</option><option v-for="recipe in state.documents" :key="recipe.id" :value="recipe.id">{{ recipe.name }} · {{ recipe.category }}</option></select></label><label>用餐场景<input v-model="cookDraft.purpose" placeholder="周末晚餐 / 工作日午餐" /></label><label>下厨人<input v-model="cookDraft.borrower" placeholder="林小满" /></label><label>烹饪日期<input v-model="cookDraft.date" type="date" required /></label><label>结果<select v-model="cookDraft.status"><option value="完成">成功完成</option><option value="翻车">翻车了</option></select></label><label>评分（1–5 星）<select v-model="cookDraft.score"><option :value="5">★★★★★ 5 星</option><option :value="4">★★★★ 4 星</option><option :value="3">★★★ 3 星</option><option :value="2">★★ 2 星</option><option :value="1">★ 1 星</option></select></label><label class="wide">备注<textarea v-model="cookDraft.note" rows="2" placeholder="这次哪里做得好，下次怎么调整？"></textarea></label></div><p class="form-tip">连续烹饪、尝试新菜系、高分记录都会实时点亮对应徽章；翻车记录会计入“零失败”的判定。</p><div class="modal-actions"><button type="button" class="secondary" @click="showCook = false">取消</button><button class="primary" type="submit" :disabled="!cookDraft.documentId"><ChefHat :size="16" />保存记录</button></div></form></div>
  </div>
</template>
